function(props) {
  // 1) MAIN COMPONENT
  function BinanceP2POffersView(props) {
    const { data } = props;
    if (!data || !data.offers) return null;

    // 2) STYLES
    const styles = {
      container: {
        backgroundColor: '#ffffff',
        padding: '12px',
        borderRadius: '4px',
        display: 'flex',
        flexWrap: 'wrap',
        gap: '12px',
        fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif'
      },
      cardWrapper: {
        width: 'calc(33.33% - 8px)',
        minWidth: '250px',
        boxSizing: 'border-box'
      },
      card: {
        position: 'relative',
        borderRadius: '6px',
        border: '1px solid #e2e8f0',
        backgroundColor: '#ffffff',
        padding: '10px 12px',
        width: '100%',
        boxSizing: 'border-box',
        transition: 'background-color 0.2s ease-in-out'
      },
      title: {
        fontWeight: '600',
        fontSize: '15px',
        marginBottom: '4px',
        color: '#1e293b'
      },
      subtitle: {
        fontSize: '12px',
        color: '#64748b',
        marginBottom: '6px'
      },
      buyBadge: {
        backgroundColor: '#DEF7EC',
        color: '#065F46',
        fontSize: '11px',
        fontWeight: '500',
        padding: '2px 6px',
        borderRadius: '4px',
        display: 'inline-block',
        marginRight: '6px',
        marginBottom: '8px'
      },
      sellBadge: {
        backgroundColor: '#FEE2E2',
        color: '#991B1B',
        fontSize: '11px',
        fontWeight: '500',
        padding: '2px 6px',
        borderRadius: '4px',
        display: 'inline-block',
        marginRight: '6px',
        marginBottom: '8px'
      },
      payment: {
        fontSize: '10px',
        backgroundColor: '#f1f5f9',
        color: '#64748b',
        borderRadius: '4px',
        padding: '2px 6px',
        marginRight: '4px',
        marginBottom: '4px',
        display: 'inline-block'
      },
      traderRow: {
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        marginTop: '8px'
      },
      traderName: {
        fontSize: '12px',
        fontWeight: '500',
        margin: 0,
        color: '#1e293b'
      },
      traderRate: {
        padding: '1px 4px',
        borderRadius: '4px',
        fontSize: '11px',
        fontWeight: '500',
        backgroundColor: '#E2E8F0',
        color: '#1e293b'
      },
      link: {
        display: 'inline-flex',
        alignItems: 'center',
        gap: '4px',
        fontSize: '12px',
        color: '#0284c7',
        textDecoration: 'none'
      }
    };

    // 3) LINK ICON
    function LinkIcon() {
      return React.createElement('svg', {
        width: '12',
        height: '12',
        viewBox: '0 0 16 16',
        fill: 'none',
        style: { color: 'currentColor' }
      }, [
        React.createElement('path', {
          key: 'p1',
          d: 'M6.5 9.5L9.5 6.5',
          stroke: 'currentColor',
          strokeWidth: '1.5',
          strokeLinecap: 'round',
          strokeLinejoin: 'round'
        }),
        React.createElement('path', {
          key: 'p2',
          d: 'M4.5 7.5L3 9C2.17157 9.82843 2.17157 11.1716 3 12C3.82843 12.8284 5.17157 12.8284 6 12L7.5 10.5',
          stroke: 'currentColor',
          strokeWidth: '1.5',
          strokeLinecap: 'round',
          strokeLinejoin: 'round'
        }),
        React.createElement('path', {
          key: 'p3',
          d: 'M8.5 5.5L10 4C10.8284 3.17157 12.1716 3.17157 13 4C13.8284 4.82843 13.8284 6.17157 13 7L11.5 8.5',
          stroke: 'currentColor',
          strokeWidth: '1.5',
          strokeLinecap: 'round',
          strokeLinejoin: 'round'
        })
      ]);
    }

    // 4) OFFER CARD
    function OfferCard({ offer }) {
      const {
        url,
        trade_type,
        price,
        available_amount,
        min_amount,
        max_amount,
        payment_methods,
        trader,
        payment_timeout,
        metadata
      } = offer;

      // Which badge style?
      const badgeStyle = trade_type === 'BUY' ? styles.buyBadge : styles.sellBadge;

      // on hover effect
      function handleMouseEnter(e) {
        e.currentTarget.style.backgroundColor = '#f8fafc';
      }
      function handleMouseLeave(e) {
        e.currentTarget.style.backgroundColor = '#ffffff';
      }

      return React.createElement(
        'div',
        {
          style: styles.card,
          onMouseEnter: handleMouseEnter,
          onMouseLeave: handleMouseLeave
        },
        // PRICE
        React.createElement('div', { style: styles.title }, `${price.toFixed(2)} ${metadata.quote_currency}`),
        // AVAILABLE
        React.createElement('div', { style: styles.subtitle }, `Available: ${available_amount.toFixed(2)} ${metadata.base_currency}`),
        // LIMIT
        React.createElement('div', { style: styles.subtitle }, `Limit: ${min_amount} - ${max_amount} ${metadata.quote_currency}`),
        // BADGE
        React.createElement('span', { style: badgeStyle }, trade_type),
        // PAYMENT METHODS
        React.createElement('div', null,
          payment_methods.map((method, i) =>
            React.createElement('span', { key: i, style: styles.payment }, method)
          )
        ),
        // TRADER INFO
        React.createElement(
          'div',
          { style: styles.traderRow },
          React.createElement('p', { style: styles.traderName }, trader.nickname),
          React.createElement('span', { style: styles.traderRate }, `${trader.completion_rate}%`)
        ),
        // OPTIONAL LINK (IF URL EXISTS)
        url && React.createElement(
          'a',
          {
            href: url,
            target: '_blank',
            rel: 'noopener noreferrer',
            style: styles.link
          },
          React.createElement(LinkIcon),
          'Open'
        )
      );
    }

    // 5) RENDER
    return React.createElement(
      'div',
      { style: styles.container },
      data.offers.map((offer, idx) =>
        React.createElement(
          'div',
          {
            key: offer.order_id || idx,
            style: styles.cardWrapper
          },
          React.createElement(OfferCard, { offer })
        )
      )
    );
  }

  // 6) RETURN
  return BinanceP2POffersView(props);
}
